import compose as C
from synth import nn
NAMES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def pcname(n): return NAMES[(n-1)%12]
SEC={2:C.SEC_A,3:C.SEC_A,4:C.SEC_B1,5:C.SEC_B2,6:C.SEC_BR,7:C.SEC_A,8:C.SEC_B2,9:C.SEC_B1,1:C.SEC_A,0:C.SEC_A}
TRIAD={'Am':{'A','C','E'},'F':{'F','A','C'},'C':{'C','E','G'},'G':{'G','B','D'},'Dm':{'D','F','A'},'E':{'E','G#','B'}}
SCALE=set('A B C D E F G'.split())
for p in range(10):
    bad=[]
    for (pp,r,ch),c in sorted(C.grid.items()):
        if pp!=p or ch not in (8,9,5,7) or 'note' not in c or c['note']==97: continue
        ch_name=SEC[p][min(3,r//16)]
        nm=pcname(c['note'])
        allowed = SCALE | TRIAD[ch_name]
        if ch_name=='E': allowed = (SCALE-{'G'}) | TRIAD['E']
        if nm not in allowed:
            bad.append((r,['','','','','','arp','','stab','lead','harm'][ch],nm,ch_name))
    print('P%d  %s  %s'%(p,SEC[p],'OK' if not bad else 'NON-SCALE: %s'%bad[:8]))
EOF"}

